import { useMemo, useState } from 'react';
import { Button } from '@jinx-ui/react';

type UserStatus = 'active' | 'disabled';

export type User = {
  id: string;
  name: string;
  role: string;
  status: UserStatus;
};

type UsersTableProps = {
  users: User[];
  pageSize?: number;
};

const STATUS_LABEL: Record<UserStatus, string> = {
  active: 'Активен',
  disabled: 'Отключён',
};

function UsersTable({ users, pageSize = 10 }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const totalPages = Math.max(1, Math.ceil(users.length / pageSize));
  const currentPage = Math.min(page, totalPages);

  const rows = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return users.slice(start, start + pageSize);
  }, [users, currentPage, pageSize]);

  const pages = useMemo(
    () => Array.from({ length: totalPages }, (_, index) => index + 1),
    [totalPages],
  );

  return (
    <div className="jx-stack">
      <table className="jx-table">
        <caption className="jx-visually-hidden">Пользователи</caption>
        <thead>
          <tr>
            <th scope="col">Имя</th>
            <th scope="col">Роль</th>
            <th scope="col">Статус</th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td colSpan={3} className="jx-table__empty">
                Пользователей нет
              </td>
            </tr>
          ) : (
            rows.map((user) => (
              <tr key={user.id}>
                <td>{user.name}</td>
                <td>{user.role}</td>
                <td>
                  <span
                    className="jx-badge"
                    style={{
                      color:
                        user.status === 'active'
                          ? 'var(--jx-success-fg)'
                          : 'var(--jx-muted-fg)',
                      background:
                        user.status === 'active'
                          ? 'var(--jx-success-bg)'
                          : 'var(--jx-muted-bg)',
                      borderRadius: 'var(--jx-radius)',
                    }}
                  >
                    {STATUS_LABEL[user.status]}
                  </span>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>

      <nav className="jx-pagination" aria-label="Постраничная навигация">
        <Button
          variant="ghost"
          disabled={currentPage === 1}
          onClick={() => setPage(currentPage - 1)}
        >
          Назад
        </Button>
        {pages.map((pageNumber) => (
          <Button
            key={pageNumber}
            variant={pageNumber === currentPage ? 'primary' : 'ghost'}
            aria-current={pageNumber === currentPage ? 'page' : undefined}
            onClick={() => setPage(pageNumber)}
          >
            {pageNumber}
          </Button>
        ))}
        <Button
          variant="ghost"
          disabled={currentPage === totalPages}
          onClick={() => setPage(currentPage + 1)}
        >
          Вперёд
        </Button>
      </nav>
    </div>
  );
}

export default UsersTable;

